# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">RİVAYET (ME\'SÛR) VE DİRAYET (RE\'Y) TEFSİRLERİNİN KARŞILAŞTIRMASI</text>\n  <rect x="20" y="44" width="320" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Rivayet Tefsiri (Naklî / Me\'sûr Tefsir)</text>\n  <rect x="34" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kaynakları: Kur\'an + Sünnet + Sahabe + Tâbiîn</text>\n  <text x="34" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Yöntemi:</tspan> Ayetleri naklî delillerle ve nüzul</text>\n  <text x="42" y="143" font-size="10" fill="#334155">sebepleriyle senetli olarak açıklar.</text>\n  <text x="34" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Dikkat Edilen Husus:</tspan> Zayıf haberler ve</text>\n  <text x="42" y="180" font-size="10" fill="#334155">İsrâiliyat rivayetlerinin ayıklanması gerekir.</text>\n  <text x="34" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#15803d">Başlıca Eserler:</tspan> Taberî (Câmiu\'l-Beyân),</text>\n  <text x="42" y="217" font-size="10" fill="#334155">İbn Kesîr (Tefsîru\'l-Kur\'âni\'l-Azîm), Süyûtî.</text>\n\n  <rect x="360" y="44" width="320" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">2. Dirayet Tefsiri (Aklî / Re\'y Tefsiri)</text>\n  <rect x="374" y="78" width="292" height="32" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Kaynakları: Nakil + Dil/Belagat + Fıkıh/Kelam + Akıl</text>\n  <text x="374" y="128" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Yöntemi:</tspan> Rivayetlerin yanında dil bilimi, mantık</text>\n  <text x="382" y="143" font-size="10" fill="#334155">ve ilmî içtihat ile derinlikli analiz yapar.</text>\n  <text x="374" y="165" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Ölçüsü:</tspan> Kur\'an ve sünnete uygun memdûh</text>\n  <text x="382" y="180" font-size="10" fill="#334155">(makbul) içtihat; hevâdan (mezmûm re\'y) kaçınma.</text>\n  <text x="374" y="202" font-size="10" fill="#334155">• <tspan font-weight="bold" fill="#1e40af">Başlıca Eserler:</tspan> Mâtürîdî, Râzî (Mefâtîhu\'l-Gayb),</text>\n  <text x="382" y="217" font-size="10" fill="#334155">Beyzâvî, Ebüssuûd, Elmalılı (Hak Dini Kur\'an Dili).</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÖRNEK BİR AYETİN TEFSİRİNDE MÜFESSİRLERİN YAKLAŞIM FARKLARI</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. İbn Kesîr Yaklaşımı (Rivayet)</text>\n  <rect x="34" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="125" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Tefsîru\'l-Kur\'âni\'l-Azîm</text>\n  <text x="32" y="126" font-size="10" fill="#334155">• Önce ayeti açıklayan diğer</text>\n  <text x="40" y="141" font-size="10" fill="#334155">Kur\'an ayetlerini bir araya getirir.</text>\n  <text x="32" y="163" font-size="10" fill="#334155">• Konuyla ilgili sahih hadisleri</text>\n  <text x="40" y="178" font-size="10" fill="#334155">ve sahabe sözlerini nakleder.</text>\n  <text x="32" y="200" font-size="10" fill="#334155">• Zayıf ve İsrâiliyat kaynaklı</text>\n  <text x="40" y="215" font-size="10" fill="#334155">haberleri tenkit ederek eler.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#ede9fe" stroke="#7c3aed" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#5b21b6">2. Râzî Yaklaşımı (Klasik Dirayet)</text>\n  <rect x="259" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#8b5cf6" stroke-width="1.5"/>\n  <text x="350" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6d28d9">Mefâtîhu\'l-Gayb (Tefsîr-i Kebîr)</text>\n  <text x="257" y="126" font-size="10" fill="#334155">• Ayetler ve sureler arasındaki</text>\n  <text x="265" y="141" font-size="10" fill="#334155">münasebet (bağlantı) yönünü kurar.</text>\n  <text x="257" y="163" font-size="10" fill="#334155">• "Mes\'ele" başlıkları altında</text>\n  <text x="265" y="178" font-size="10" fill="#334155">dil, kelam ve fıkıh tahlili yapar.</text>\n  <text x="257" y="200" font-size="10" fill="#334155">• Kevnî ayetleri dönemin astronomi</text>\n  <text x="265" y="215" font-size="10" fill="#334155">ve tabiat ilimleriyle açıklar.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">3. Elmalılı Yaklaşımı (Çağdaş)</text>\n  <rect x="484" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="575" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Hak Dini Kur\'an Dili</text>\n  <text x="482" y="126" font-size="10" fill="#334155">• Klasik rivayet ve dirayet</text>\n  <text x="490" y="141" font-size="10" fill="#334155">birikimini ustalıkla sentezler.</text>\n  <text x="482" y="163" font-size="10" fill="#334155">• Eşsiz bir Türkçe belagatle</text>\n  <text x="490" y="178" font-size="10" fill="#334155">kelime ve nükteleri çözümler.</text>\n  <text x="482" y="200" font-size="10" fill="#334155">• Modern felsefi ve sosyal</text>\n  <text x="490" y="215" font-size="10" fill="#334155">şüphelere güçlü cevaplar verir.</text>\n</svg>', '<svg viewBox="0 0 700 255" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="255" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TERCÜME, MEAL VE TEFSİR KAVRAMLARININ KARŞILAŞTIRMASI</text>\n  <rect x="20" y="44" width="210" height="194" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">1. Tercüme (Birebir Çeviri)</text>\n  <rect x="34" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="125" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">Tam Eş Değer Aktarım</text>\n  <text x="32" y="126" font-size="10" fill="#334155">• Bir metnin başka bir dile</text>\n  <text x="40" y="141" font-size="10" fill="#334155">anlam ve üslup kaybı olmadan</text>\n  <text x="40" y="156" font-size="10" fill="#334155">birebir aktarılmasıdır.</text>\n  <text x="32" y="180" font-size="10" font-weight="bold" fill="#991b1b">• Kur\'an İçin Durumu:</text>\n  <text x="32" y="196" font-size="9.5" fill="#334155">Kur\'an\'ın i\'câzı ve çok katmanlı</text>\n  <text x="32" y="210" font-size="9.5" fill="#334155">lafzı sebebiyle birebir tercümesi</text>\n  <text x="32" y="224" font-size="9.5" fill="#334155">mümkün görülmemiştir.</text>\n\n  <rect x="245" y="44" width="210" height="194" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">2. Meal (Yaklaşık Öz Anlam)</text>\n  <rect x="259" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="350" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Kısa ve Yaklaşık Çeviri</text>\n  <text x="257" y="126" font-size="10" fill="#334155">• Çok anlamlı ayet lafızlarından</text>\n  <text x="265" y="141" font-size="10" fill="#334155">birincil anlamın seçilerek veciz</text>\n  <text x="265" y="156" font-size="10" fill="#334155">biçimde başka dile aktarımıdır.</text>\n  <text x="257" y="180" font-size="10" font-weight="bold" fill="#92400e">• Sınırları:</text>\n  <text x="257" y="196" font-size="9.5" fill="#334155">Ayrıntılı sebeb-i nüzul ve fıkhi</text>\n  <text x="257" y="210" font-size="9.5" fill="#334155">bağlamı içermez; tek başına hüküm</text>\n  <text x="257" y="224" font-size="9.5" fill="#334155">çıkarmak için yeterli değildir.</text>\n\n  <rect x="470" y="44" width="210" height="194" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">3. Tefsir (Geniş Açıklama)</text>\n  <rect x="484" y="78" width="182" height="30" rx="6" fill="#ffffff" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="97" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kapsamlı İlmî Beyan</text>\n  <text x="482" y="126" font-size="10" fill="#334155">• Ayetlerin dil, belagat, nüzul</text>\n  <text x="490" y="141" font-size="10" fill="#334155">sebebi, hadis ve sahabe nakilleriyle</text>\n  <text x="490" y="156" font-size="10" fill="#334155">derinlemesine açıklanmasıdır.</text>\n  <text x="482" y="180" font-size="10" font-weight="bold" fill="#15803d">• İşlevi:</text>\n  <text x="482" y="196" font-size="9.5" fill="#334155">Çok anlamlı lafızların bütün</text>\n  <text x="482" y="210" font-size="9.5" fill="#334155">yönlerini, tarihsel bağlamını ve</text>\n  <text x="482" y="224" font-size="9.5" fill="#334155">ilahi muradı tam olarak ortaya koyar.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
